def reconnect_attempts(settings=None):
    """How many attempts one write may take across a dropped connection (DB-2751)."""
    if settings is None:
        settings = load_settings()
    return (settings.get("db") or {})["reconnect_attempts"]


def execute(op, connect, settings=None):
    """Perform one write. Returns whatever the connection's run() returns.

    Each attempt runs on a fresh connection to the system of record. If an attempt raises
    `TransientConnectionError` the operation is re-issued on a new connection, up to
    `db.reconnect_attempts` attempts in total; when that budget is used up the last error is
    let out. Nothing else is retried.
    """
    if settings is None:
        settings = load_settings()
    attempts = reconnect_attempts(settings)
    while True:
        connection = connect(primary_dsn(settings))
        try:
            return connection.run(op)
        except TransientConnectionError:
            attempts -= 1
            if attempts <= 0:
                raise

